function [y] = flow_filter(hf, hm, tau, dt)
%FLOW_FILTER  The filtered momentum [N m s] after a step dt toward the measured momentum hm, time constant tau [s].
%   hf: real[1] (passed a plain number)
%   hm: real[1] (passed a plain number)
%   tau: real[1] (passed a plain number)
%   dt: real[1] (passed a plain number)
%   returns y: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    y = 0;
    y = (hf + ((dt / (tau + dt)) * (hm - hf)));
end
